bounded_host_request.command:
set -eu; python3 - <<'PY'
import subprocess,hashlib,secrets,json
def sql(q):
 r=subprocess.run(["docker","exec","deploy-postgres-1","psql","-U","gace","-d","gaybbs","-At","-c",q],capture_output=True,text=True,check=True)
 return r.stdout.strip()
js="""const fs=require('fs'),https=require('https');let s='';process.stdin.on('data',x=>s+=x);process.stdin.on('end',()=>{const d=JSON.parse(s),t=process.env.BOT_TOKEN_FILE?fs.readFileSync(process.env.BOT_TOKEN_FILE,'utf8').trim():process.env.BOT_TOKEN,b=JSON.stringify(d.payload);const r=https.request({hostname:'api.telegram.org',path:'/bot'+t+'/'+d.method,method:'POST',family:4,timeout:15000,headers:{'Content-Type':'application/json','Content-Length':Buffer.byteLength(b)}},res=>{let x='';res.on('data',z=>x+=z);res.on('end',()=>{try{console.log(JSON.stringify(JSON.parse(x)))}catch{process.exitCode=2}})});r.on('error',()=>process.exitCode=3);r.end(b)})"""
def api(method,payload):
 r=subprocess.run(["docker","exec","-i","deploy-gaybbs-1","node","-e",js],input=json.dumps(dict(method=method,payload=payload)),text=True,capture_output=True,check=True)
 return json.loads(r.stdout)
rows=sql("SELECT p.chat_id,p.message_thread_id,p.message_id FROM topic_dm_entry_pins p JOIN posting_topics t ON t.chat_id=p.chat_id AND t.message_thread_id=p.message_thread_id WHERE p.message_thread_id=1695 AND p.chat_id IN (-1002373696859,-1003770334893) AND p.state='published' AND p.pinned=true AND p.message_id>0 AND t.enabled=true AND t.purpose='announcement' AND t.verified_at IS NOT NULL").splitlines()
if len(rows)!=1: raise Exception("PRECONDITION_FAILED")
chat,thread,old=map(int,rows[0].split('|'))
r=api("pinChatMessage",dict(chat_id=chat,message_id=old,disable_notification=True))
if r.get("ok") or r.get("error_code")!=400 or "message to pin not found" not in r.get("description","").lower():raise Exception("OLD_MESSAGE_NOT_CONFIRMED_MISSING")
tok=secrets.token_urlsafe(24); h=hashlib.sha256(("GayBBS-menu-v1:"+tok).encode()).hexdigest()
q=f"UPDATE topic_dm_entry_pins SET state='publishing',pinned=false,message_id=NULL,token_hash='{h}',updated_at=NOW() WHERE chat_id={chat} AND message_thread_id={thread} AND message_id={old} AND state='published' AND pinned=true RETURNING message_thread_id"
if sql(q)!=str(thread):raise Exception("CONCURRENT_CHANGE")
r=api("sendMessage",dict(chat_id=chat,message_thread_id=thread,text="📝 このトピックに投稿するには、下のボタンからBotのDMへ移動してください。",reply_markup=dict(inline_keyboard=[[dict(text="📝 投稿メニューを開く",url="https://t.me/GayBBS_bot?start=p_"+tok)]])))
mid=r.get("result",{}).get("message_id")
if not r.get("ok") or not isinstance(mid,int) or mid<1:raise Exception("SEND_UNCERTAIN")
if sql(f"UPDATE topic_dm_entry_pins SET message_id={mid},updated_at=NOW() WHERE chat_id={chat} AND message_thread_id={thread} AND state='publishing' AND token_hash='{h}' RETURNING message_id")!=str(mid):raise Exception("SAVE_MESSAGE_UNCERTAIN")
r=api("pinChatMessage",dict(chat_id=chat,message_id=mid,disable_notification=True))
if not r.get("ok"):raise Exception("PIN_UNCERTAIN")
if sql(f"UPDATE topic_dm_entry_pins SET state='published',pinned=true,updated_at=NOW() WHERE chat_id={chat} AND message_thread_id={thread} AND message_id={mid} AND state='publishing' RETURNING message_id")!=str(mid):raise Exception("READBACK_FAILED")
print("REPAIR_1695=PASS OLD="+str(old)+" NEW="+str(mid))
PY
